class CustomActivation(nn.Module):
    """Learnable Exponential Linear Unit (LELU).

    LELU(x) = x if x >= 0 else α * (exp(x) - 1)
    where α > 0 is a learnable parameter per activation instance.
    This generalizes ELU (α=1) and allows adaptive negative saturation level.
    """

    def __init__(self):
        super().__init__()
        # Learnable parameter α, initialized to 1.0 (standard ELU)
        self.log_alpha = nn.Parameter(torch.tensor(0.0))  # log(α)

    def forward(self, x):
        alpha = torch.exp(self.log_alpha)  # ensures positivity
        return torch.where(x >= 0, x, alpha * (torch.exp(x) - 1))
